let id = 1045;
const langs = ['da','nl','fr','es'];

process.stdout.write(`--\n-- Daten für Tabelle \`animaltext\` (da/nl/fr/es), Biome 300+400\n-- ${animals.length} Tiere × 4 Sprachen = ${animals.length*4} Zeilen, IDs ${id}–${id+animals.length*4-1}\n--\n\n`);
process.stdout.write(`INSERT INTO \`animaltext\` (\`id\`, \`animalId\`, \`languageCode\`, \`animalName\`, \`animalDescription\`) VALUES\n`);

const rows = [];
for (const a of animals) {
  const [animalId, ...rest] = a;
  for (let i = 0; i < 4; i++) {
    const lang = langs[i];
    const name = rest[i];
    const desc = rest[4+i];
    rows.push(`(${id++}, ${animalId}, '${lang}', '${q(name)}', '${q(desc)}')`);
  }
}
process.stdout.write(rows.join(',\n') + ';\n');
process.stderr.write(`Generated ${rows.length} rows, IDs ${1045}–${id-1}\n`);
